from pathlib import Path
import json
p=Path('frontend/eval-round1/dashboard.html'); s=p.read_text(encoding='utf-8'); a=s.find('<section id="eval3-final"'); b=s.find('</section>',a)+10
j=json.loads(Path('docs/interview/eval no 3/eval3-reviewed-report.json').read_text(encoding='utf-8')); m=j['summary']['metrics']; rows=''.join(f"<tr><td><strong>{c['id']}</strong><br><span class='case-id'>{c.get('category','')}</span></td><td><span class='status-pill'>{'通过' if not c.get('error') else '未通过'}</span></td><td><span class='status-pill'>程序评分</span></td><td>{c.get('metrics',{}).get('total_tokens',0):,}</td><td>{c.get('metrics',{}).get('tool_errors',0)}</td><td>{c.get('metrics',{}).get('paused_runs',0)}</td></tr>" for c in j['cases'])
sec=f'''<section id="eval3-final" class="round2-block"><div class="section-heading"><div><div class="section-kicker">第三轮评测</div><h2>Eval3 · Luna 20题复核结果</h2><p class="lead">结果由助手逐题判断；过程、效率、安全、可用性沿用程序评分。429 与网络中断单独记录。</p></div></div><div class="grid kpis"><article class="card kpi"><div class="kpi-label">执行题数</div><div class="kpi-value">20<small>/ 20</small></div></article><article class="card kpi"><div class="kpi-label">总 tokens</div><div class="kpi-value">{m.get('total_tokens',0):,}</div></article><article class="card kpi"><div class="kpi-label">缓存占比</div><div class="kpi-value">{m.get('cache_ratio',0)*100:.2f}%</div></article><article class="card kpi"><div class="kpi-label">工具调用 / 错误</div><div class="kpi-value">{m.get('tool_calls',0)} / {m.get('tool_errors',0)}</div></article><article class="card kpi"><div class="kpi-label">阶段暂停</div><div class="kpi-value">{m.get('paused_runs',0)}</div></article></div><article class="card case-card"><div class="table-meta"><span>显示 20 / 20 道 · 最新 Eval3</span><span>结果：助手判断 · 其余：程序判断</span></div><div class="table-scroll"><table class="case-table"><thead><tr><th>案例 / 能力</th><th>结果</th><th>过程</th><th>Tokens</th><th>工具错误</th><th>暂停</th></tr></thead><tbody>{rows}</tbody></table></div></article><p class="round2-limit"><a href="../../docs/interview/eval%20no%203/eval3-reviewed-report.json">下载完整复核报告</a></p></section>'''
p.write_text(s[:a]+sec+s[b:],encoding='utf-8')
